extra_css:
/* Event Horizon surfaces: panels are smoked glass in orbit, edged by a thin warm rim like the photon ring (brighter on one side,
   as the disk is), with the starfield bending faintly behind them. Hover pulls a panel a little toward you. Own surfaces only. */
html[data-atmo="horizon"] .card, html[data-atmo="horizon"] .panel, html[data-atmo="horizon"] .gx-card {
  background: radial-gradient(140% 90% at 0% 0%, rgba(255,174,92,.08), transparent 50%), linear-gradient(180deg, rgba(20,16,26,.72), rgba(4,3,7,.88));
  backdrop-filter: blur(16px) saturate(130%); -webkit-backdrop-filter: blur(16px) saturate(130%);
  box-shadow: inset 1px 1px 0 rgba(255,190,120,.35), inset -1px -1px 0 rgba(140,160,255,.12), 0 0 30px rgba(255,140,60,.06), 0 24px 60px rgba(0,0,0,.8);
  transition: transform .45s cubic-bezier(.2,1,.3,1), box-shadow .45s; }
html[data-atmo="horizon"] .card:hover, html[data-atmo="horizon"] .gx-card:hover {
  transform: translateY(-3px) scale(1.005); box-shadow: inset 1px 1px 0 rgba(255,200,140,.6), inset -1px -1px 0 rgba(140,160,255,.2), 0 0 40px rgba(255,140,60,.14), 0 30px 70px rgba(0,0,0,.85); }
html[data-atmo="horizon"] h1, html[data-atmo="horizon"] h2 { font-weight: 300; letter-spacing: .06em; text-shadow: 0 0 18px rgba(255,160,80,.35); }

